namespace sv_40541a8d5a6449e0a061b24eae9a6031.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors = new()
    {
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Williams",
        "Dr. Brown"
    };

    private static readonly Dictionary<string, List<string>> DoctorTimeSlots = new()
    {
        ["Dr. Smith"] = new() { "9:00 AM", "10:00 AM", "11:00 AM", "2:00 PM", "3:00 PM" },
        ["Dr. Johnson"] = new() { "8:00 AM", "10:00 AM", "1:00 PM", "4:00 PM" },
        ["Dr. Williams"] = new() { "9:30 AM", "10:30 AM", "2:30 PM", "3:30 PM" },
        ["Dr. Brown"] = new() { "8:30 AM", "11:30 AM", "1:30 PM", "4:30 PM" }
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        if (DoctorTimeSlots.TryGetValue(doctor, out var slots))
        {
            return Task.FromResult(slots);
        }
        return Task.FromResult(new List<string>());
    }

    /// <summary>
    /// Validates patient and appointment details server-side.
    /// Returns a dictionary of field name -> error message for any validation failures.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Simulate: "taken@example.com" has an outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors["Email"] = "Account has outstanding balance";
        }

        // Simulate: Dr. Smith does not accept self-pay patients
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        // Simulate: 10:00 AM slot was just taken (race condition)
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_40541a8d5a6449e0a061b24eae9a6031.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* STEP 1: Patient Information *@
    <fieldset>
        <legend>Step 1: Patient Information</legend>

        <div class="mb-3">
            <label for="patientName" class="form-label">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label for="email" class="form-label">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.ContainsKey("Email"))
            {
                <div class="validation-message">@serverErrors["Email"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="phone" class="form-label">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label for="insurance" class="form-label">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* STEP 2: Appointment Details *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2: Appointment Details</legend>

            <div class="mb-3">
                <label for="doctor" class="form-label">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor" @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.ContainsKey("Doctor"))
                {
                    <div class="validation-message">@serverErrors["Doctor"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="date" class="form-label">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate" @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label for="timeSlot" class="form-label">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.ContainsKey("TimeSlot"))
                {
                    <div class="validation-message">@serverErrors["TimeSlot"]</div>
                }
            </div>

            <div class="mb-3">
                <label for="reason" class="form-label">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => Model.ReasonForVisit" />
            </div>

            <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability">
                Check Availability
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || serverErrors.Count > 0)">
                Book Appointment
            </button>
        </fieldset>
    }
</EditForm>

@if (bookingConfirmed)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private bool showStep2;
    private bool availabilityChecked;
    private bool bookingConfirmed;
    private List<string> doctors = new();
    private List<string> availableSlots = new();
    private Dictionary<string, string> serverErrors = new();
    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields manually
        editContext = new EditContext(Model);
        var validationMessages = new ValidationMessageStore(editContext);

        bool step1Valid = true;

        if (string.IsNullOrWhiteSpace(Model.PatientName))
            step1Valid = false;
        if (string.IsNullOrWhiteSpace(Model.Email) || !IsValidEmail(Model.Email))
            step1Valid = false;
        if (string.IsNullOrWhiteSpace(Model.Phone))
            step1Valid = false;
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
            step1Valid = false;

        if (step1Valid)
        {
            showStep2 = true;
            serverErrors.Clear();
            availabilityChecked = false;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        serverErrors.Remove("Doctor");
        serverErrors.Remove("TimeSlot");
        Model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                Model.Doctor, DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
        else
        {
            availableSlots = new();
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();

        // Basic step 2 validation before calling service
        if (string.IsNullOrEmpty(Model.Doctor) ||
            !Model.AppointmentDate.HasValue ||
            string.IsNullOrEmpty(Model.TimeSlot) ||
            string.IsNullOrWhiteSpace(Model.ReasonForVisit))
        {
            return;
        }

        if (Model.AppointmentDate.Value.Date <= DateTime.Today)
        {
            serverErrors["Date"] = "Date must be in the future";
            return;
        }

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        if (errors.Count > 0)
        {
            serverErrors = errors;
            availabilityChecked = false;
        }
        else
        {
            availabilityChecked = true;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityChecked && serverErrors.Count == 0)
        {
            bookingConfirmed = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }

    public class AppointmentModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient name is required")]
        public string PatientName { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required")]
        [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Invalid email format")]
        public string Email { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required")]
        public string Phone { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance provider is required")]
        public string InsuranceProvider { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Doctor is required")]
        public string Doctor { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required")]
        public DateTime? AppointmentDate { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Time slot is required")]
        public string TimeSlot { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason for visit is required")]
        [System.ComponentModel.DataAnnotations.MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer")]
        public string ReasonForVisit { get; set; } = string.Empty;
    }
}

